import React, { useState } from 'react';
import { Container, Button, Alert } from 'react-bootstrap';
import { FaPlus } from 'react-icons/fa';
import Summary from './Summary';
import FilterBar from './FilterBar';
import EntryList from './EntryList';
import EntryForm from './EntryForm';
import useEntries from '../hooks/useEntries';
import useAuth from '../hooks/useAuth';
import Spinner from './common/Spinner';

const Dashboard = () => {
  const { user } = useAuth();
  const { 
    entries, 
    summary, 
    loading, 
    error, 
    filters,
    addEntry,
    editEntry,
    removeEntry,
    applyFilters,
    resetFilters,
    refreshEntries
  } = useEntries();
  
  const [showEntryForm, setShowEntryForm] = useState(false);
  const [editingEntry, setEditingEntry] = useState(null);
  const [deleteError, setDeleteError] = useState(null);
  
  // Handle opening the form for a new entry
  const handleAddEntry = () => {
    setEditingEntry(null);
    setShowEntryForm(true);
  };
  
  // Handle opening the form for editing
  const handleEditEntry = (entry) => {
    setEditingEntry(entry);
    setShowEntryForm(true);
  };
  
  // Handle form submission (create or update)
  const handleSubmitEntry = async (formData) => {
    if (editingEntry) {
      await editEntry(editingEntry.id, formData);
    } else {
      await addEntry(formData);
    }
  };
  
  // Handle deleting an entry
  const handleDeleteEntry = async (entryId) => {
    try {
      setDeleteError(null);
      const success = await removeEntry(entryId);
      
      if (!success) {
        setDeleteError('Failed to delete the entry. Please try again.');
      }
    } catch (err) {
      setDeleteError('An error occurred while deleting the entry.');
    }
  };

  if (!user) {
    return (
      <Container className="py-4">
        <Alert variant="warning">
          Please log in to view your budget dashboard.
        </Alert>
      </Container>
    );
  }

  return (
    <Container className="py-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h1>Budget Dashboard</h1>
        <Button 
          variant="primary" 
          onClick={handleAddEntry}
          disabled={loading}
        >
          <FaPlus className="me-2" />
          Add New Entry
        </Button>
      </div>
      
      {/* Summary Cards */}
      <Summary summary={summary} />
      
      {/* Filter Bar */}
      <FilterBar 
        filters={filters} 
        applyFilters={applyFilters} 
        resetFilters={resetFilters} 
      />
      
      {/* Delete Error Alert */}
      {deleteError && (
        <Alert 
          variant="danger" 
          dismissible 
          onClose={() => setDeleteError(null)}
          className="mb-4"
        >
          {deleteError}
        </Alert>
      )}
      
      {/* Entries List */}
      <EntryList 
        entries={entries}
        loading={loading}
        error={error}
        onEdit={handleEditEntry}
        onDelete={handleDeleteEntry}
      />
      
      {loading && <Spinner text="Loading data..." />}
      
      {/* Entry Form Modal */}
      <EntryForm 
        isOpen={showEntryForm}
        onClose={() => setShowEntryForm(false)}
        onSubmit={handleSubmitEntry}
        initialData={editingEntry}
        isEditing={!!editingEntry}
      />
    </Container>
  );
};

export default Dashboard;
